window.MealComposer=(()=>{const form=document.querySelector('#mealForm'),host=document.createElement('section');host.className='dish-composer';form.elements.name.closest('label').after(host);function dishes(){return Array.isArray(state.savedDishes)?state.savedDishes:[];}function render(){host.innerHTML='<h3>My dishes</h3><p class="tiny">Save your own dishes with nutrition per serving. Tap one to fill this meal, then adjust for your portion.</p><div class="saved-dishes">'+dishes().map((d,i)=>'<div class="saved-dish"><button class="secondary" type="button" data-use="'+i+'">'+safe(d.name)+'</button><button class="text-button" type="button" data-remove-dish="'+i+'" aria-label="Remove '+safe(d.name)+' from saved dishes">Remove</button></div>').join('')+'</div><p class="tiny">'+(dishes().length?'Removing a saved dish keeps previously logged meals.':'No saved dishes yet. Fill in the meal name and nutrition below, then save it here.')+'</p><button class="secondary" type="button" id="saveMyDish">Save / update this dish</button><p id="dishSaveStatus" role="status"></p>';host.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{const d=dishes()[Number(b.dataset.use)];form.elements.name.value=d.name;for(const k of ['calories','protein','carbs','fat'])form.elements[k].value=d[k]??'';ingredients=[];document.querySelector('#ingredients').innerHTML='';});host.querySelectorAll('[data-remove-dish]').forEach(b=>b.onclick=()=>{const previous=dishes().slice();state.savedDishes=dishes().filter((_,i)=>i!==Number(b.dataset.removeDish));if(!save())state.savedDishes=previous;render();});host.querySelector('#saveMyDish').onclick=()=>{if(!form.elements.name.value.trim()||!['calories','protein','carbs'].every(k=>form.elements[k].value!==''&&form.elements[k].checkValidity())||!form.elements.fat.checkValidity()){host.querySelector('#dishSaveStatus').textContent='Enter a name and valid calories, protein and carbs first.';return;}const d={id:crypto.randomUUID(),name:form.elements.name.value.trim()};for(const k of ['calories','protein','carbs','fat'])d[k]=form.elements[k].value===''?null:Number(form.elements[k].value);const previous=dishes().slice(),next=previous.slice(),i=next.findIndex(x=>x.name.toLowerCase()===d.name.toLowerCase());if(i>=0)next[i]=d;else next.push(d);state.savedDishes=next;if(!save())state.savedDishes=previous;render();host.querySelector('#dishSaveStatus').textContent='Dish saved to your library.';};}document.addEventListener('meal:opened',render);render();return {current:null,clearEstimate(){}};})();